# -*- coding: utf-8 -*-
"""
Avellaneda-Stoikov Market Making & Microstructure LOB Cloud Trainer (Kaggle Production)
Trains:
1. Microstructure Price Drift Regressor (LightGBM)
2. Adverse Selection Shock Classifiers (P_toxic_down, P_toxic_up)
3. Optimal Control Parameters (gamma, kappa, alpha_drift, beta_toxic) via Genetic Search
"""
import sys, os, json, time, math, random, gzip, base64
import numpy as np
import pandas as pd
import lightgbm as lgb
import numba as nb
from datetime import datetime, timezone

RAW_B64 = """"""
raw_bytes = gzip.decompress(base64.b64decode(RAW_B64.encode('ascii')))
arr = np.frombuffer(raw_bytes, dtype=np.float32).reshape(-1, 9)

open_ = arr[:, 0].astype(np.float64)
high = arr[:, 1].astype(np.float64)
low = arr[:, 2].astype(np.float64)
close = arr[:, 3].astype(np.float64)
volume = arr[:, 4].astype(np.float64)
p_vol = arr[:, 5].astype(np.float64)
gk_vol = arr[:, 6].astype(np.float64)
atr14 = arr[:, 7].astype(np.float64)
bar_ofi = arr[:, 8].astype(np.float64)
n = len(close)

print(f"Loaded {n} sampled high-frequency micro bars on Kaggle.")

# Feature Engineering
s_c = pd.Series(close)
ma20 = s_c.rolling(20).mean().bfill().values
f_dev = (close - ma20) / np.maximum(atr14, 0.05)
s_r1 = s_c.pct_change(1).fillna(0).values
vol_ma = pd.Series(volume).rolling(20).mean().bfill().values
vol_accel = np.clip(volume / (vol_ma + 1e-9), 0.01, 50.0)

# Multi-Horizon Labels
H = 5
fwd_ret = (pd.Series(close).shift(-H).values - close) / np.maximum(atr14, 0.05)
fwd_min = (pd.Series(low).rolling(H).min().shift(-H).values - close) / np.maximum(atr14, 0.05)
fwd_max = (pd.Series(high).rolling(H).max().shift(-H).values - close) / np.maximum(atr14, 0.05)

# Toxic Shocks: Down crash <= -1.8 ATR, Up surge >= 1.8 ATR
y_toxic_down = (fwd_min <= -1.8).astype(np.int32)
y_toxic_up = (fwd_max >= 1.8).astype(np.int32)
y_drift = np.clip(fwd_ret, -5.0, 5.0)

X = np.column_stack([p_vol, gk_vol, atr14, bar_ofi, f_dev, s_r1, vol_accel])

# Train LightGBM Drift Model
valid_len = int(n * 0.70)
dtrain_drift = lgb.Dataset(X[:valid_len], label=y_drift[:valid_len])
params_drift = {'objective': 'regression', 'metric': 'rmse', 'learning_rate': 0.08, 'num_leaves': 15, 'verbosity': -1}
bst_drift = lgb.train(params_drift, dtrain_drift, num_boost_round=50)

# Train Toxic Down Model
dtrain_tox_down = lgb.Dataset(X[:valid_len], label=y_toxic_down[:valid_len])
params_tox = {'objective': 'binary', 'metric': 'auc', 'learning_rate': 0.08, 'num_leaves': 12, 'verbosity': -1}
bst_tox_down = lgb.train(params_tox, dtrain_tox_down, num_boost_round=40)

# Train Toxic Up Model
dtrain_tox_up = lgb.Dataset(X[:valid_len], label=y_toxic_up[:valid_len])
bst_tox_up = lgb.train(params_tox, dtrain_tox_up, num_boost_round=40)

# Predict micro signals on full dataset
pred_drift = bst_drift.predict(X)
pred_tox_down = bst_tox_down.predict(X)
pred_tox_up = bst_tox_up.predict(X)

print(f"ML models trained successfully. Drift std: {pred_drift.std():.4f}, ToxDown mean: {pred_tox_down.mean():.4f}")

# Numba JIT Optimal Control Parameter Search
@nb.njit(fastmath=True)
def eval_as_market_maker(c, h, l, sig_vol, mu_drift, p_tox_d, p_tox_u,
                         gamma, kappa, alpha_d, beta_tox, lot_size, s_idx, e_idx):
    n_pts = e_idx - s_idx
    cash = 100000.0; init_cash = cash
    q = 0.0 # inventory in units
    maker_fee = 0.0001 # 1.0 bps Maker fee
    trades = 0; wins = 0; pnl_sum = 0.0; max_eq = cash; max_dd = 0.0
    
    for i in range(n_pts - 1):
        t = s_idx + i
        mid = c[t]; hi = h[t]; lo = l[t]
        sigma = max(0.10, sig_vol[t])
        
        # Reservation Price Tilt
        r = mid - (q * lot_size) * gamma * (sigma ** 2) * mid * 0.001 + alpha_d * mu_drift[t] * (mid * 0.0005)
        # Optimal Half Spread
        half_spd = (1.0 / gamma) * math.log(1.0 + gamma / kappa) * (mid * 0.0004)
        half_spd = max(mid * 0.0002, half_spd)
        
        delta_ask = half_spd * (1.0 + beta_tox * p_tox_u[t])
        delta_bid = half_spd * (1.0 + beta_tox * p_tox_d[t])
        
        ask_p = r + delta_ask
        bid_p = r - delta_bid
        
        allow_bid = (p_tox_d[t] < 0.65) and (q < 10.0)
        allow_ask = (p_tox_u[t] < 0.65) and (q > -10.0)
        
        # Passive Maker Fill Execution Simulation
        if allow_bid and lo <= bid_p:
            fill_p = bid_p
            fee = fill_p * lot_size * maker_fee
            cash -= (fill_p * lot_size + fee)
            q += 1.0
            trades += 1
            
        if allow_ask and hi >= ask_p:
            fill_p = ask_p
            fee = fill_p * lot_size * maker_fee
            cash += (fill_p * lot_size - fee)
            q -= 1.0
            trades += 1
            
        eq = cash + (q * lot_size) * mid
        if eq > max_eq: max_eq = eq
        dd = (max_eq - eq) / max_eq
        if dd > max_dd: max_dd = dd
        
    tot_ret = (cash + (q * lot_size) * c[e_idx-1] - init_cash) / init_cash
    calmar = tot_ret / (max_dd + 1e-4) if max_dd > 0 else 0.0
    fitness = tot_ret * 10.0 + calmar * 3.0 - 25.0 * (max_dd ** 2)
    return fitness, tot_ret, max_dd, trades

# Genetic Search for Best Optimal Control Genome
best_fit = -9999.0
best_params = (0.08, 1.8, 0.35, 1.20)
is_end = valid_len

for _ in range(50):
    g = round(random.uniform(0.04, 0.16), 4)
    k = round(random.uniform(1.2, 2.8), 4)
    ad = round(random.uniform(0.15, 0.60), 4)
    bt = round(random.uniform(0.8, 2.2), 4)
    
    fit, ret, dd, tr = eval_as_market_maker(
        close, high, low, gk_vol, pred_drift, pred_tox_down, pred_tox_up,
        g, k, ad, bt, 0.05, 0, is_end
    )
    if fit > best_fit and tr >= 50:
        best_fit = fit
        best_params = (g, k, ad, bt)

# OOS Blind Evaluation on Out-of-Sample slice
oos_fit, oos_ret, oos_dd, oos_trades = eval_as_market_maker(
    close, high, low, gk_vol, pred_drift, pred_tox_down, pred_tox_up,
    best_params[0], best_params[1], best_params[2], best_params[3], 0.05, is_end, n
)

checkpoint = {
    "model_name": "BTC-Avellaneda-Stoikov-Microstructure-Certified",
    "timestamp_utc": datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ"),
    "optimal_as_parameters": {
        "gamma_risk_aversion": best_params[0],
        "kappa_order_intensity": best_params[1],
        "drift_alpha": best_params[2],
        "toxic_beta": best_params[3],
        "lot_size": 0.05,
        "maker_fee_bps": 1.0,
        "min_spread_bps": 2.0
    },
    "out_of_sample_metrics": {
        "oos_bars_count": n - is_end,
        "total_return_pct": round(oos_ret * 100, 2),
        "max_drawdown_pct": round(oos_dd * 100, 2),
        "total_trades": int(oos_trades),
        "calmar_ratio": round(oos_ret / (oos_dd + 1e-4), 2)
    }
}

with open("as_mm_checkpoint.json", "w", encoding="utf-8") as f:
    json.dump(checkpoint, f, indent=2)

print("✔ Checkpoint exported successfully to as_mm_checkpoint.json!")
print(json.dumps(checkpoint, indent=2))
